(()=>{
 'use strict';document.documentElement.classList.add('js');
 const root=document.body.dataset.root||'./',it=document.documentElement.lang==='it',sidebar=document.querySelector('.sidebar'),main=document.querySelector('main'),toggle=document.querySelector('.menu-toggle'),media=matchMedia('(max-width:800px)');
 const theme=document.querySelector('.theme-toggle'),themeKey='think-journal-theme:'+new URL('../',document.currentScript.src).pathname;
 try{const stored=localStorage.getItem(themeKey);if(['dark','light'].includes(stored))document.documentElement.dataset.theme=stored;}catch{}
 theme.hidden=false;theme.onclick=()=>{const dark=document.documentElement.dataset.theme?document.documentElement.dataset.theme==='dark':matchMedia('(prefers-color-scheme:dark)').matches;document.documentElement.dataset.theme=dark?'light':'dark';try{localStorage.setItem(themeKey,dark?'light':'dark');}catch{}};
 const backdrop=document.createElement('button');backdrop.className='menu-backdrop';backdrop.hidden=true;backdrop.tabIndex=-1;backdrop.setAttribute('aria-label',toggle.dataset.close);document.body.append(backdrop);
 const openLabel=toggle.getAttribute('aria-label');
 function menu(open){open=open&&media.matches;document.body.classList.toggle('menu-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?toggle.dataset.close:openLabel);backdrop.hidden=!open;main.inert=open;if(open)sidebar.querySelector('input,a,button')?.focus({preventScroll:true});else toggle.focus({preventScroll:true});}
 toggle.onclick=()=>menu(!document.body.classList.contains('menu-open'));backdrop.onclick=()=>menu(false);media.addEventListener('change',()=>{if(document.body.classList.contains('menu-open'))menu(false);});
 document.addEventListener('keydown',event=>{if(!document.body.classList.contains('menu-open'))return;if(event.key==='Escape'){event.preventDefault();menu(false);}if(event.key==='Tab'){const nodes=[toggle,...sidebar.querySelectorAll('a,button,input')].filter(n=>n.getClientRects().length&&!n.disabled);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
 const form=document.querySelector('.site-search'),input=form.querySelector('input'),status=form.querySelector('.search-status'),nav=document.querySelector('.article-list'),pagination=document.querySelector('.default-pagination'),original=[...nav.childNodes];form.hidden=false;form.onsubmit=e=>e.preventDefault();let indexPromise,timer,request=0;
 const normalize=s=>s.normalize('NFKD').replace(/\p{M}/gu,'').toLocaleLowerCase();
 async function search(){const epoch=++request,query=input.value.trim();if(!query){nav.replaceChildren(...original);pagination.hidden=false;status.textContent='';return;}status.textContent=it?'Ricerca…':'Searching…';try{
  indexPromise??=fetch(root+'search-index.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(rows=>rows.map(r=>({...r,haystack:normalize(r.title+' '+r.text)}))).catch(e=>{indexPromise=null;throw e;});
  const rows=await indexPromise;if(epoch!==request)return;const terms=normalize(query).split(/\s+/),matches=rows.filter(r=>terms.every(q=>r.haystack.includes(q)));nav.replaceChildren();pagination.hidden=true;status.textContent=matches.length+' '+(it?'risultati':'results');let count=0;
  const more=document.createElement('button');more.textContent=it?'Mostra altri':'Show more';
  const append=()=>{more.remove();for(const row of matches.slice(count,count+40)){const a=document.createElement('a'),time=document.createElement('time'),title=document.createElement('span');a.href=root+row.path;time.dateTime=new Date(row.created).toISOString();time.textContent=new Intl.DateTimeFormat(it?'it-IT':'en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(row.created));title.textContent=row.title;a.append(time,title);nav.append(a);}count+=40;if(count<matches.length)nav.append(more);};more.onclick=append;append();
 }catch{if(epoch===request)status.textContent=it?'Ricerca disponibile quando il sito è servito via HTTP/HTTPS.':'Search is available when the site is served over HTTP/HTTPS.';}}
 input.addEventListener('input',()=>{clearTimeout(timer);++request;timer=setTimeout(search,160);});
})();
